INSERT INTO gold."fato_pedidos" ("order_id","customer_id","order_status","order_purchase_timestamp","order_approved_at","order_delivered_carrier_date","order_delivered_customer_date","order_estimated_delivery_date","cliente_sk","localizacao_sk","data_compra_sk","data_aprovacao_sk","data_transportadora_sk","data_entrega_sk","data_previsao_entrega_sk") SELECT o."order_id",o."customer_id",o."order_status",o."order_purchase_timestamp",o."order_approved_at",o."order_delivered_carrier_date",o."order_delivered_customer_date",o."order_estimated_delivery_date",CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(dc.cliente_sk,-2) END::bigint AS "cliente_sk",CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(dl.localizacao_sk,-2) END::bigint AS "localizacao_sk",CASE WHEN o."order_purchase_timestamp" IS NULL THEN -1 ELSE COALESCE(dt0.data_sk,-2) END::bigint AS "data_compra_sk",CASE WHEN o."order_approved_at" IS NULL THEN -1 ELSE COALESCE(dt1.data_sk,-2) END::bigint AS "data_aprovacao_sk",CASE WHEN o."order_delivered_carrier_date" IS NULL THEN -1 ELSE COALESCE(dt2.data_sk,-2) END::bigint AS "data_transportadora_sk",CASE WHEN o."order_delivered_customer_date" IS NULL THEN -1 ELSE COALESCE(dt3.data_sk,-2) END::bigint AS "data_entrega_sk",CASE WHEN o."order_estimated_delivery_date" IS NULL THEN -1 ELSE COALESCE(dt4.data_sk,-2) END::bigint AS "data_previsao_entrega_sk" FROM silver."olist_orders_dataset" o LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_clientes dc ON dc.customer_unique_id=c.customer_unique_id LEFT JOIN gold.dim_localizacao dl ON dl.customer_zip_code_prefix=c.customer_zip_code_prefix AND dl.customer_city=c.customer_city AND dl.customer_state=c.customer_state LEFT JOIN gold.dim_calendario dt0 ON dt0.dia=o."order_purchase_timestamp"::date LEFT JOIN gold.dim_calendario dt1 ON dt1.dia=o."order_approved_at"::date LEFT JOIN gold.dim_calendario dt2 ON dt2.dia=o."order_delivered_carrier_date"::date LEFT JOIN gold.dim_calendario dt3 ON dt3.dia=o."order_delivered_customer_date"::date LEFT JOIN gold.dim_calendario dt4 ON dt4.dia=o."order_estimated_delivery_date"::date  WHERE TRUE ON CONFLICT ("order_id") DO NOTHING;
INSERT INTO gold."fato_itens_pedido" ("order_id","order_item_id","product_id","seller_id","shipping_limit_date","price","freight_value","customer_id","order_status","order_purchase_timestamp","cliente_sk","localizacao_sk","produto_sk","vendedor_sk","data_compra_sk","data_limite_envio_sk") SELECT src."order_id",src."order_item_id",src."product_id",src."seller_id",src."shipping_limit_date",src."price",src."freight_value",o.customer_id,o.order_status,o.order_purchase_timestamp,CASE WHEN o.order_id IS NULL THEN -2 WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(dc.cliente_sk,-2) END::bigint AS "cliente_sk",CASE WHEN o.order_id IS NULL THEN -2 WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(dl.localizacao_sk,-2) END::bigint AS "localizacao_sk",CASE WHEN src.product_id IS NULL THEN -1 ELSE COALESCE(dp.produto_sk,-2) END::bigint AS "produto_sk",CASE WHEN src.seller_id IS NULL THEN -1 ELSE COALESCE(dv.vendedor_sk,-2) END::bigint AS "vendedor_sk",CASE WHEN o.order_id IS NULL THEN -2 WHEN o."order_purchase_timestamp" IS NULL THEN -1 ELSE COALESCE(dt0.data_sk,-2) END::bigint AS "data_compra_sk",CASE WHEN src."shipping_limit_date" IS NULL THEN -1 ELSE COALESCE(dt1.data_sk,-2) END::bigint AS "data_limite_envio_sk" FROM silver."olist_order_items_dataset" src LEFT JOIN silver.olist_orders_dataset o ON o.order_id=src.order_id LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_clientes dc ON dc.customer_unique_id=c.customer_unique_id LEFT JOIN gold.dim_localizacao dl ON dl.customer_zip_code_prefix=c.customer_zip_code_prefix AND dl.customer_city=c.customer_city AND dl.customer_state=c.customer_state LEFT JOIN gold.dim_produtos dp ON dp.product_id=src.product_id LEFT JOIN gold.dim_vendedores dv ON dv.seller_id=src.seller_id LEFT JOIN gold.dim_calendario dt0 ON dt0.dia=o."order_purchase_timestamp"::date LEFT JOIN gold.dim_calendario dt1 ON dt1.dia=src."shipping_limit_date"::date  WHERE TRUE ON CONFLICT ("order_id","order_item_id") DO NOTHING;
INSERT INTO gold."fato_pagamentos" ("order_id","payment_sequential","payment_type","payment_installments","payment_value","customer_id","order_status","order_purchase_timestamp","cliente_sk","localizacao_sk","forma_pagamento_sk","data_compra_sk") SELECT src."order_id",src."payment_sequential",src."payment_type",src."payment_installments",src."payment_value",o.customer_id,o.order_status,o.order_purchase_timestamp,CASE WHEN o.order_id IS NULL THEN -2 WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(dc.cliente_sk,-2) END::bigint AS "cliente_sk",CASE WHEN o.order_id IS NULL THEN -2 WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(dl.localizacao_sk,-2) END::bigint AS "localizacao_sk",CASE WHEN src.payment_type IS NULL THEN -1 ELSE COALESCE(df.forma_pagamento_sk,-2) END::bigint AS "forma_pagamento_sk",CASE WHEN o.order_id IS NULL THEN -2 WHEN o."order_purchase_timestamp" IS NULL THEN -1 ELSE COALESCE(dt0.data_sk,-2) END::bigint AS "data_compra_sk" FROM silver."olist_order_payments_dataset" src LEFT JOIN silver.olist_orders_dataset o ON o.order_id=src.order_id LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_clientes dc ON dc.customer_unique_id=c.customer_unique_id LEFT JOIN gold.dim_localizacao dl ON dl.customer_zip_code_prefix=c.customer_zip_code_prefix AND dl.customer_city=c.customer_city AND dl.customer_state=c.customer_state LEFT JOIN gold.dim_forma_pagamento df ON df.payment_type=src.payment_type LEFT JOIN gold.dim_calendario dt0 ON dt0.dia=o."order_purchase_timestamp"::date  WHERE TRUE ON CONFLICT ("order_id","payment_sequential") DO NOTHING;
